import React from "react";
import cafeImg from "../assets/Corner-cafe.webp";

function Home() {
  return (
    <Box sx={{p: {xs:2, md:4}, maxWidth: 900, mx: "auto"}}>
      {/* Main photo */}
      <Box component="img" src= {cafeImg} alt=" Cafe inner image" sx={{width: "100%", borderRadius: 3, mb: 0, maxHeight: 350, objectFit: "cover"}} />


    </Box>
  );
}

export default Home;
